package com.splendordashboard;
import android.app.*;import android.content.*;import android.os.*;
public class PowerReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){String a=i.getAction();if(a==null)return;AppPrefs p=new AppPrefs(c);if(Intent.ACTION_POWER_CONNECTED.equals(a)){p.set("lastPower",1);notifyUser(c,"Power connected","USB/charging detected. Tap to open the dashboard.");}else if(Intent.ACTION_POWER_DISCONNECTED.equals(a)){p.set("lastPower",0);notifyUser(c,"Power disconnected","USB/charging ended. Ignition state is not guaranteed.");}else if(Intent.ACTION_BOOT_COMPLETED.equals(a)&&p.autoStart()){notifyUser(c,"Dashboard ready","Android may restrict automatic activity launches. Tap to open the dashboard.");}}void notifyUser(Context c,String title,String body){NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel("dashboard","Dashboard",NotificationManager.IMPORTANCE_LOW));PendingIntent pi=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"dashboard"):new Notification.Builder(c);b.setContentTitle(title).setContentText(body).setSmallIcon(android.R.drawable.ic_menu_compass).setContentIntent(pi).setAutoCancel(true);nm.notify(101,b.build());}}